private int parseEndOfLine(String headerPart, int end) {
    // Handle invalid input
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Find the index of the \r\n sequence
    int index = headerPart.indexOf("\r\n", end);

    if (index == -1) {
        // If the \r\n sequence is not found, return the length of the string
        return headerPart.length();
    } else {
        // Otherwise, return the index of the \r\n sequence
        return index;
    }
}

private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length() && headerPart.charAt(index) != '\r' && headerPart.charAt(index) != '\n') {
        index++;
    }
    if (index == headerPart.length()) {
        throw new IllegalArgumentException("Parse error: Reached end of header part without finding end of line");
    }
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    int eol;
    for (eol = end; eol >= 0; eol--) {
        if (headerPart.charAt(eol) == '\r' && headerPart.charAt(eol + 1) == '\n') {
            break;
        }
    }
    return eol;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || headerPart.isEmpty()) {
        throw new IllegalArgumentException("Header part cannot be null or empty");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("End index must be greater than or equal to 0 and less than the length of the header part");
    }
    int startIndex = end;
    while (startIndex < headerPart.length() && headerPart.charAt(startIndex) != '\r' && headerPart.charAt(startIndex) != '\n') {
        startIndex++;
    }
    if (startIndex == headerPart.length()) {
        throw new IllegalArgumentException("End of line not found");
    }
    return startIndex;
}

private int parseEndOfLine(String headerPart, int end) {
    // Reasoning:
    // The method is designed to skip bytes until the end of the current line,
    // as indicated by the \r\n sequence. The method takes two parameters:
    // - headerPart: a String containing the headers, which are being parsed.
    // - end: an integer indicating the index of the last byte that has yet been processed.
    // The method returns an integer indicating the index of the \r\n sequence,
    // which indicates the end of the line.

    // Check for invalid inputs:
    if (headerPart == null || end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("Invalid input: headerPart=" + headerPart + ", end=" + end);
    }

    // Initialize the index of the \r\n sequence to -1:
    int eol = -1;

    // Loop through the input string until the \r\n sequence is found:
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
            eol = i;
            break;
        }
    }

    // Return the index of the \r\n sequence:
    return eol;
}

