public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Step 1: Check for null input
    if (graph == null) {
        throw new IllegalArgumentException("Null input graph.");
    }

    // Step 2: Build the identity mapping
    Map<V, V> mapping = new HashMap<>();
    for (V vertex : graph.vertices()) {
        mapping.put(vertex, vertex);
    }

    // Step 3: Check for unmapped vertices
    if (mapping.size() != graph.vertices().size()) {
        throw new IllegalStateException("Failed to map all vertices.");
    }

    // Step 4: Return the identity mapping
    return new IsomorphicGraphMapping<>(graph, mapping);
}

