public static void forceDeleteOnExit(File file) throws IOException {
	// Check if file is null
	if (file == null) {
		throw new NullPointerException("File must not be null");
	}

	if (file.isDirectory()) {
		// Delete directory and all sub-directories
		File[] subFiles = file.listFiles();
		if (subFiles != null) {
			for (File subFile : subFiles) {
				if (subFile.isDirectory()) {
					// Recursively delete sub-directory
					forceDeleteOnExit(subFile);
				} else {
					// Delete sub-file
					subFile.delete();
				}
			}
		}
	} else {
		// Delete file
		file.delete();
	}

	// Schedule deletion on JVM exit
	Runtime.getRuntime().addShutdownHook(new Thread(() -> {
		try {
			file.delete();
		} catch (IOException e) {
			// Ignore exception
		}
	}));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File cannot be null");
    }
    if (file.isFile()) {
        file.deleteOnExit();
    } else if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                forceDeleteOnExit(f);
            }
        }
        file.deleteOnExit();
    } else {
        throw new IOException("File does not exist or is not a file or directory");
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // Check if file is a directory
    if (file.isDirectory()) {
        // If file is a directory, delete it and all sub-directories
        File[] subFiles = file.listFiles();
        if (subFiles != null) {
            for (File subFile : subFiles) {
                forceDeleteOnExit(subFile);
            }
        }
    }
    // Delete the file
    if (!file.delete()) {
        throw new IOException("Failed to delete file: " + file.getPath());
    }
}

