for (E edge: graph.getEdges()) {
if (limitedGraph.getEdgeCount() < limit) {
limitedGraph.addEdge(edge.getLeftVertex(), edge.getRightVertex());
}
}

return limitedGraph;
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Define a map to store the bipartite graph
    Map<String,V> bipartiteGraph = new HashMap<>();

    // Loop through the vertices in the target graph
    for (V vertex : target.getVertices()) {
        // Add the vertex to the bipartite graph
        bipartiteGraph.addVertex(vertex);

        // Loop through the edges in the target graph
        for (E edge : target.getEdges()) {
            // Check if the edge is connected to the vertex
            if (edge.getSource() == vertex || edge.getDestination() == vertex) {
                // Add the edge to the bipartite graph
                bipartiteGraph.addEdge(edge);
            }
        }
    }

    // Add the bipartite graph to the result map
    resultMap.add("bipartite_graph", bipartiteGraph);
}

@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // check if the graph is bipartite
    if (!isBipartite(target)) {
        throw new IllegalArgumentException("The graph is not bipartite");
    }

    // create a map to store the vertices in each partition
    Map<String, List<V>> partitionMap = new HashMap<>();
    for (V vertex : target.getVertices()) {
        String partition = getPartition(vertex);
        if (!partitionMap.containsKey(partition)) {
            partitionMap.put(partition, new ArrayList<>());
        }
        partitionMap.get(partition).add(vertex);
    }

    // create a map to store the edges between partitions
    Map<String, List<E>> edgeMap = new HashMap<>();
    for (E edge : target.getEdges()) {
        String sourcePartition = getPartition(edge.getSourceVertex());
        String targetPartition = getPartition(edge.getTargetVertex());
        if (!edgeMap.containsKey(sourcePartition)) {
            edgeMap.put(sourcePartition, new ArrayList<>());
        }
        edgeMap.get(sourcePartition).add(edge);

        if (!edgeMap.containsKey(targetPartition)) {
            edgeMap.put(targetPartition, new ArrayList<>());
        }
        edgeMap.get(targetPartition).add(edge);
    }

    // create a new graph with the same vertices and edges as the original graph
    Graph<V,E> completeGraph = new Graph<>(target.getVertices(), target.getEdges());

    // add new vertices and edges to the complete graph
    for (String partition : partitionMap.keySet()) {
        for (V vertex : partitionMap.get(partition)) {
            for (E edge : edgeMap.get(partition)) {
                if (!completeGraph.hasVertex(edge.getTargetVertex())) {
                    completeGraph.addVertex(edge.getTargetVertex());
                }
                if (completeGraph.hasEdge(edge.getSourceVertex(), edge.getTargetVertex())) {
                    throw new IllegalArgumentException("The graph is not bipartite");
                }
                completeGraph.addEdge(edge.getSourceVertex(), edge.getTargetVertex());
            }
        }
    }

    // remove excess edges
    for (E edge : completeGraph.getEdges()) {
        if (edgeMap.containsKey(edge.getSourceVertex()) && edgeMap.containsKey(edge.getTargetVertex())) {
            completeGraph.removeEdge(edge);
        }
    }

    // return the complete bipartite graph
    resultMap.put("completeGraph", completeGraph);
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target and result map must be non-null");
    }

    Set<String> keys = resultMap.keySet();
    if (keys.size() != 2) {
        throw new IllegalArgumentException("Result map must have exactly two entries");
    }

    V v1 = resultMap.get(keys.iterator().next());
    V v2 = resultMap.get(keys.iterator().next());
    if (v1.equals(v2)) {
        throw new IllegalArgumentException("Vertices in result map must be distinct");
    }

    Graph<V, E> generatedGraph = new Graph<V, E>(2);

    // Add vertices to graph
    generatedGraph.addVertex(v1);
    generatedGraph.addVertex(v2);

    // Connect vertices with directed edges
    for (int i = 0; i < 2; i++) {
        generatedGraph.addEdge(new Edge<V, E>(v1, v2));
        generatedGraph.addEdge(new Edge<V, E>(v2, v1));
    }

    target = generatedGraph;
}

protected int findByte(byte value, int pos) {
    // Check if the buffer is null or empty
    if (buffer == null || buffer.length == 0) {
        return -1;
    }

    // Check if the position is valid
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }

    // Start searching from the specified position
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }

    // If the value was not found, return -1
    return -1;
}

