public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
  int size = 0;

  if (out == null || message == null || schema == null || buffer == null) {
    throw new IllegalArgumentException("Invalid input: out=" + out + ", message=" + message
        + ", schema=" + schema + ", buffer=" + buffer);
  }

  // Serialize the message using the given schema
  LinkedBuffer linkedBuffer = new LinkedBuffer(buffer.size());
  ProtobufOutput protobufOutput = new ProtobufOutput(out, linkedBuffer);
  schema.writeTo(protobufOutput, message);
  size = linkedBuffer.getSize();

  // Write the length of the message as a varint
  VarintOutput varintOutput = new VarintOutput(out);
  varintOutput.writeVarint32(size);

  return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = 0;

    // Get the size of the message in bytes
    try {
        size = ProtobufIOUtil.computeDelimitedSize(message, schema, buffer);
    } catch (IOException e) {
        throw new IOException("Failed to compute delimited size", e);
    }

    // Write the size of the message
    try {
        out.write(size);
    } catch (IOException e) {
        throw new IOException("Failed to write message size", e);
    }

    // Write the message itself
    try {
        ProtobufIOUtil.writeDelimitedTo(out, message, schema, buffer);
    } catch (IOException e) {
        throw new IOException("Failed to write message", e);
    }

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }

    // Serialize the message
    byte[] bytes = schema.serialize(message);

    // Write the message size
    out.write(bytes.length);

    // Write the message
    out.write(bytes);

    // Flush the buffer
    buffer.flush();

    // Return the number of bytes written
    return bytes.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
  if (out == null || message == null || schema == null || buffer == null) {
    throw new IOException("Invalid input: out=" + out + ", message=" + message
        + ", schema=" + schema + ", buffer=" + buffer);
  }

  int messageSize = schema.getSize(message);
  int headerSize = writeRawVarint32(out, messageSize);
  schema.writeTo(message, out);
  return headerSize + messageSize;
}

