public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] arguments = new Class[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            arguments[i] = resolveTypeArgument(typeArguments[i], targetType);
        }
        return arguments;
    } else {
        return null;
    }
}

private static Class<?> resolveTypeArgument(Type type, Class<?> targetType) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (upperBounds.length == 1) {
            return resolveTypeArgument(upperBounds[0], targetType);
        } else {
            throw new IllegalArgumentException("Invalid wildcard type: " + type);
        }
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
        for (int i = 0; i < typeParameters.length; i++) {
            if (typeParameters[i].equals(typeVariable)) {
                return typeParameters[i].resolve(targetType);
            }
        }
        throw new IllegalArgumentException("Type variable not found: " + typeVariable);
    } else {
        throw new IllegalArgumentException("Invalid type: " + type);
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
        }
        return resolvedArguments;
    } else {
        return null;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Return null if genericType is not a parameterized type
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the actual type arguments from the genericType
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Return null if typeArguments is empty
    if (typeArguments.length == 0) {
        return null;
    }

    // Resolve the type arguments using the type variable information for targetType
    Class<?>[] resolvedTypeArguments = new Class[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof TypeVariable) {
            Type[] bounds = ((TypeVariable) typeArgument).getBounds();
            if (bounds.length == 1) {
                resolvedTypeArguments[i] = (Class<?>) bounds[0];
            } else {
                throw new IllegalArgumentException("Type parameter " + typeArgument + " has multiple bounds");
            }
        } else if (typeArgument instanceof ParameterizedType) {
            resolvedTypeArguments[i] = (Class<?>) ((ParameterizedType) typeArgument).getRawType();
        } else {
            throw new IllegalArgumentException("Unknown type argument " + typeArgument);
        }
    }

    return resolvedTypeArguments;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Step 1: Check if genericType is actually parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;

    // Step 2: Get the type arguments of the parameterized type
    Type[] typeArguments = parameterizedType.getActualTypeArguments();

    // Step 3: Check if typeArguments is empty
    if (typeArguments.length == 0) {
        return null;
    }

    // Step 4: Create a list to store the resolved class objects
    List<Class<?>> resolvedClasses = new ArrayList<>();

    // Step 5: Loop through each type argument and resolve it to a class object
    for (Type typeArgument : typeArguments) {
        Class<?> resolvedClass = resolveType(typeArgument, targetType);
        if (resolvedClass != null) {
            resolvedClasses.add(resolvedClass);
        }
    }

    // Step 6: Return the resolved class objects as an array
    return resolvedClasses.toArray(new Class<?>[]{});
}

private static Class<?> resolveType(Type type, Class<?> targetType) {
    // Step 1: Check if type is a class
    if (type instanceof Class) {
        return (Class<?>) type;
    }

    // Step 2: Check if type is a type variable
    if (type instanceof TypeVariable) {
        // Step 2.1: Get the type variable's name
        String typeVariableName = ((TypeVariable) type).getName();

        // Step 2.2: Get the type variable's declaration
        TypeDeclaration typeDeclaration = targetType.getTypeDeclaration();

        // Step 2.3: Find the type variable in the type declaration's type variables
        Optional<TypeVariable> optionalTypeVariable = typeDeclaration.getTypeVariables().stream()
                .filter(tv -> tv.getName().equals(typeVariableName))
                .findFirst();

        // Step 2.4: If the type variable is found, resolve it to a class object
        if (optionalTypeVariable.isPresent()) {
            TypeVariable typeVariable = optionalTypeVariable.get();
            String typeVariableBound = typeVariable.getType() instanceof Class ? typeVariable.getType().getSimpleName() : "?";
            return new ResolvedTypeVariable(typeVariableName, typeVariableBound).getTypeVariableClass();
        }
    }

    // Step 3: Check if type is a wildcard type
    if (type instanceof WildcardType) {
        // Step 3.1: Get the wildcard type's lower bounds
        List<Type> lowerBounds = ((WildcardType) type).getLowerBounds();

        // Step 3.2: If there are lower bounds, use the first one to resolve the type variable
        if (lowerBounds.size() > 0) {
            return resolveType(lowerBounds.get(0), targetType);
        }
    }

    // Step 4: Return null if the type cannot be resolved
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] typeParams = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class) {
                typeParams[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof TypeVariable) {
                TypeVariable typeVariable = (TypeVariable) typeArgument;
                typeParams[i] = resolveTypeVariable(typeVariable, targetType);
            } else {
                throw new IllegalStateException("Unsupported type argument: " + typeArgument);
            }
        }
        return typeParams;
    }
    return null;
}

@Override
public void accept(METRICS data) {
    if (data == null) {
        throw new IllegalArgumentException("Null data");
    }

    // Merge the data with the existing value
    Object value = data.getData();

    // If the value is null, set it to an empty map
    if (value == null) {
        value = new HashMap<>();
    }

    // Check if the value is a map
    if (!(value instanceof Map)) {
        throw new IllegalArgumentException("Invalid data type");
    }

    // Merge the data with the existing value
    Map<String, Object> existingMap = (Map<String, Object>) data.getData();
    Map<String, Object> newMap = (Map<String, Object>) value;

    for (String key : newMap.keySet()) {
        Object newValue = newMap.get(key);

        if (existingMap.containsKey(key)) {
            Object existingValue = existingMap.get(key);

            // If the existing value is a list, append the new value to the list
            if (existingValue instanceof List) {
                List<Object> existingList = (List<Object>) existingValue;
                existingList.add(newValue);
            } else {
                // If the existing value is a map, recursively merge the new map with the existing map
                if (newValue instanceof Map) {
                    Map<String, Object> existingSubMap = (Map<String, Object>) existingValue;
                    Map<String, Object> newSubMap = (Map<String, Object>) newValue;
                    mergeMaps(existingSubMap, newSubMap);
                } else {
                    // The existing value is not a list or map, so replace it with the new value
                    existingMap.put(key, newValue);
                }
            }
        } else {
            // The new key does not exist in the existing map, so add it
            existingMap.put(key, newValue);
        }
    }
}

