    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION.toMillis();
    long rangeStart = start;
    long rangeEnd = Math.min(start + duration, end);
    while (rangeEnd <= end) {
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
        rangeStart = rangeEnd;
        rangeEnd = Math.min(rangeStart + duration, end);
    }
    return timeRanges;
