public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            size += 4;
            i++;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    // step 1: validate input
    if (str == null || index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // step 2: calculate size
    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(c)) {
            size += 4;
        } else {
            size += 3;
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Check for null string
    if (str == null) {
        throw new NullPointerException("str cannot be null");
    }

    // Check for invalid index
    if (index < 0 || index > str.length()) {
        throw new IndexOutOfBoundsException("index must be non-negative and less than or equal to the length of str");
    }

    // Check for invalid length
    if (len < 0 || len > str.length() - index) {
        throw new IndexOutOfBoundsException("len must be non-negative and less than or equal to the length of str minus index");
    }

    // Compute the size of the UTF-8 string
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int cp = str.charAt(i);
        if (cp <= 0x7F) {
            size++;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }

    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index out of bounds");
    }

    if (len < 0 || len > str.length() - index) {
        throw new IllegalArgumentException("Length out of bounds");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        size += getUtf8ByteLength(str.charAt(i));
    }

    return size;
}

private static int getUtf8ByteLength(int codePoint) {
    if (codePoint < 0x80) {
        return 1;
    } else if (codePoint < 0x800) {
        return 2;
    } else if (codePoint < 0x10000) {
        return 3;
    } else if (codePoint < 0x200000) {
        return 4;
    } else if (codePoint < 0x4000000) {
        return 5;
    } else {
        return 6;
    }
}

