public Set<V> computePositiveDegreeVertices(Graph<V, E> graph) {
    Set<V> positiveDegreeVertices = new HashSet<>();
    for (Edge<V, E> edge : graph.getEdges()) {
        positiveDegreeVertices.add(edge.getSource());
        positiveDegreeVertices.add(edge.getDestination());
    }
    return positiveDegreeVertices;
}

