    utf8Bytes = str.toString().getBytes("UTF-8");
  } catch (UnsupportedEncodingException e) {
    throw new IllegalArgumentException("UTF-8 encoding is not supported.", e);
  }

  // Write utf8-encoded bytes to the LinkedBuffer
  try {
    lb.write(utf8Bytes);
  } catch (IOException e) {
    throw new RuntimeException("Failed to write utf8-encoded bytes to LinkedBuffer.", e);
  }

  return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
	// Check if the input string is null
	if (str == null) {
		throw new NullPointerException("The input string cannot be null");
	}

	// Check if the LinkedBuffer is null
	if (lb == null) {
		throw new NullPointerException("The LinkedBuffer cannot be null");
	}

	// Check if the WriteSession is null
	if (session == null) {
		throw new NullPointerException("The WriteSession cannot be null");
	}

	// Get the UTF-8 bytes from the input string
	byte[] utf8Bytes = str.getBytes(StandardCharsets.UTF_8);

	// Write the bytes to the LinkedBuffer
	lb.write(utf8Bytes);

	// Return the updated LinkedBuffer
	return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Validate input
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Invalid input");
    }
    // Reserve space for the bytes in the LinkedBuffer
    int utf8BytesLen = 0;
    for (int i = 0; i < str.length(); i++) {
        utf8BytesLen += 1;
    }
    if (utf8BytesLen > lb.getCapacity()) {
        throw new IllegalArgumentException("Insufficient capacity in LinkedBuffer");
    }
    // Write the utf8-encoded bytes into the LinkedBuffer
    try {
        for (int i = 0; i < str.length(); i++) {
            byte[] utf8Bytes = str.charAt(i).toString().getBytes("UTF-8");
            for (byte utf8Byte : utf8Bytes) {
                lb.write(utf8Byte);
            }
        }
    } catch (UnsupportedEncodingException e) {
        throw new IllegalStateException("Invalid encoding", e);
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) throws CharacterCodingException {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Convert the String to a byte array
    byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);

    // Write the bytes to the LinkedBuffer
    lb.write(bytes, 0, bytes.length);

    return lb;
}

public void removeFromTreeEdgeList() {
    if (leftChild == null && rightChild == null) {
        // If the node has no children, we can simply remove it from its parent's child list
        parent.removeChild(this);
    } else {
        // If the node has children, we need to find its predecessor and successor
        Edge predecessor = leftChild.findPredecessor();
        Edge successor = rightChild.findSuccessor();

        // Update the child list of the predecessor to skip over this node
        predecessor.removeChild(this);
        predecessor.addChild(rightChild);

        // Update the child list of the successor to skip over this node
        successor.removeChild(leftChild);
        successor.addChild(this);

        // Remove this node from its parent's child list
        parent.removeChild(this);
    }
}

