    if(this.leftEdge != null){
        this.leftEdge.removeFromTreeEdgeList();
        this.leftEdge = null;
    }
    // Step 3: Remove from right edge list
    if(this.rightEdge != null){
        this.rightEdge.removeFromTreeEdgeList();
        this.rightEdge = null;
    }
    // Step 4: Remove from tree edge list
    if(this.treeEdge != null){
