public void removeFromTreeEdgeList() {
  // Step 1: Handle null-pointer check for this edge
  if (this == null) {
    throw new IllegalArgumentException("This edge is null. Cannot remove from tree edge list.");
  }

  // Step 2: Handle invalid edge check
  if (!isValidEdge()) {
    throw new IllegalArgumentException("This edge is invalid. Cannot remove from tree edge list.");
  }

  // Step 3: Remove this edge from the previous and next edges' list of this edge's doubly linked list
  if (prev != null) {
    prev.next = next;
  }
  if (next != null) {
    next.prev = prev;
  }

  // Step 4: Update this edge's doubly linked list
  prev = null;
  next = null;
}

private boolean isValidEdge() {
  if (this == null) {
    return false;
  }

  if (prev == null && next == null) {
    return false;
  }

  return true;
}

public void removeFromTreeEdgeList(){
    // Step 1: Check if the edge is part of a tree edge list
    if (!isPartOfTreeEdgeList()) {
        return;
    }

    // Step 2: Remove the edge from the tree edge list of its left and right subtrees
    leftSubtree.removeFromTreeEdgeList(this);
    rightSubtree.removeFromTreeEdgeList(this);

    // Step 3: Update the doubly linked list of tree edges
    if (previous != null) {
        previous.next = next;
    }
    if (next != null) {
        next.previous = previous;
    }

    // Step 4: Update the edge's properties
    previous = null;
    next = null;
    setLeftSubtree(null);
    setRightSubtree(null);
}

public void removeFromTreeEdgeList() {
    if (this.previousInTree == null && this.nextInTree == null) {
        // Edge is not part of any tree, so return without doing anything
        return;
    }

    if (this.previousInTree == null && this.nextInTree != null) {
        // Edge is the first edge in the tree, so we need to update the next edge's previous pointer
        this.nextInTree.previousInTree = null;
    } else if (this.previousInTree != null && this.nextInTree == null) {
        // Edge is the last edge in the tree, so we need to update the previous edge's next pointer
        this.previousInTree.nextInTree = null;
    } else {
        // Edge is in the middle of the tree, so we need to update the previous and next edges' pointers
        this.previousInTree.nextInTree = this.nextInTree;
        this.nextInTree.previousInTree = this.previousInTree;
    }

    // Set the edge's previous and next pointers to null
    this.previousInTree = null;
    this.nextInTree = null;
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    Matcher matcher = Pattern.compile("\\$\\{([^\\}]+)\\}").matcher(value);
    while (matcher.find()) {
        String subKey = matcher.group(1);
        String subValue = findAndSubst(subKey, props);
        if (subValue == null) {
            return null;
        }

        value = matcher.replaceFirst(subValue);
    }

    return value;
}

public static String findAndSubst(String key, Properties props) {
