  }
  String value = props.getProperty(key);
  if (value == null) {
    throw new IllegalArgumentException("Key not found in properties");
  }
  String substitutedValue = value;
  Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
  Matcher matcher = pattern.matcher(value);
  while (matcher.find()) {
    String match = matcher.group(1);
    String replacement = props.getProperty(match);
    if (replacement == null) {
      throw new IllegalArgumentException("No value found for property " + match);
    } else {
      substitutedValue = substitutedValue.replace("${" + match + "}", replacement);
    }
  }
  return substitutedValue;
}

