public static String findAndSubst(String key, Properties props) {
  String value = props.getProperty(key);
  if (value == null) {
    return null;
  }

  Map<String, String> variables = getVariables(value);
  for (Map.Entry<String, String> entry : variables.entrySet()) {
    String variable = entry.getKey();
    String replacement = entry.getValue();
    value = value.replaceAll(Pattern.quote(variable), replacement);
  }

  return value;
}

private static Map<String, String> getVariables(String value) {
  Map<String, String> variables = new HashMap<>();
  Pattern pattern = Pattern.compile("\\$\\{([^}]+)}");
  Matcher matcher = pattern.matcher(value);
  while (matcher.find()) {
    String variable = matcher.group(1);
    String replacement = props.getProperty(variable);
    if (replacement == null) {
      throw new IllegalArgumentException("No value found for variable '" + variable + "'");
    }
    variables.put(variable, replacement);
  }
  return variables;
}

