public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    String[] segments = u.getPath().split("/");
    for (int i = 0; i < segments.length; i++) {
        String segment = segments[i];
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
        }
        result.add(new PathSegmentImpl(segment));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }

    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path != null) {
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        if (decode) {
            path = URLDecoder.decode(path, "UTF-8");
        }
        segments = Arrays.asList(path.split("/"));
    }

    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
  List<PathSegmentImpl> pathSegments = new ArrayList<>();
  String path = u.getPath();
  if(path != null && !path.isEmpty()){
      String[] segments = path.split(URLEncodedUtils.PATH_SEPARATORS);
      for(String segment : segments){
          if(segment.isEmpty()){
              continue;
          }
          PathSegmentImpl pathSegment = new PathSegmentImpl();
          pathSegment.setPath(segment);
          pathSegment.setDecoded(decode);
          pathSegments.add(pathSegment);
      }
  }
  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  List<PathSegmentImpl> pathSegments = new ArrayList<>();

  String rawPath = u.getRawPath();
  if (rawPath == null || rawPath.isEmpty()) {
    return pathSegments;
  }

  String[] pathSegmentStrings = rawPath.split("/");
  for (String pathSegmentString : pathSegmentStrings) {
    pathSegments.add(new PathSegmentImpl(pathSegmentString, decode));
  }

  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Decode the path component of the URI
    String path = u.getPath();
    if (path.isEmpty()) {
        return Collections.emptyList();
    }

    List<String> segments = new ArrayList<>();
    int start = 0;
    while (start < path.length()) {
        int beginIndex = path.indexOf('/', start);
        if (beginIndex == -1) {
            break;
        }
        start = beginIndex + 1;
        int endIndex = path.indexOf('/', start);
        if (endIndex == -1) {
            endIndex = path.length();
        }
        String segment = path.substring(start, endIndex);
        start = endIndex + 1;
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }
        segments.add(segment);
    }

    return segments;
}

