public void valueAccumulation(String key, Long value) {
    // Check if the key is valid
    if (key == null || key.isEmpty()) {
        throw new IllegalArgumentException("Key must not be null or empty");
    }

    // Check if the value is valid
    if (value == null) {
        throw new IllegalArgumentException("Value must not be null");
    }

    // Get the existing value for the key, if any
    Long existingValue = map.get(key);

    // Accumulate the new value with the existing value, if present
    if (existingValue != null) {
        value += existingValue;
    }

    // Update the map with the new value
    map.put(key, value);
}

public void valueAccumulation(String key, Long value){
// Handle null value
if (key == null || value == null) {
throw new IllegalArgumentException("Key or value cannot be null");
}

// If the map does not contain the given key, add it with the initial value
if (!map.containsKey(key)) {
map.put(key, value);
} else {
// Otherwise, accumulate the value with the existing value
map.put(key, map.get(key) + value);
}
}

