  if (key == null || value == null) {
    throw new IllegalArgumentException("Key and value cannot be null");
  }

  // Get the existing value associated with the key
  Long existingValue = get(key);

  // If there is no existing value, set the new value
  if (existingValue == null) {
    put(key, value);
  } else {
    // If there is an existing value, update it with the new value
    put(key, existingValue + value);
  }
}

public InputStream next() throws IOException {
  if (currentFile == null) {
    throw new IOException("No files available");
  }

  try {
    currentFile = currentFile.listFiles()[0];
    return new FileInputStream(currentFile);
  } catch (IOException e) {
    throw new IOException("Error reading next file", e);
  }
}

public InputStream next() throws IOException {
    // Check if there are more files available
    if (currentIndex < files.size()) {
        // Get the next file
        File nextFile = files.get(currentIndex);
        currentIndex++;
        // Return an input stream for the file
        return new FileInputStream(nextFile);
    } else {
        // No more files available, return null
        return null;
    }
}

