private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Invalid type or method descriptor: null");
    }
    int numTypesToPop = descriptor.length();
    for (int i = 0; i < numTypesToPop; i++) {
        Type type;
        if (descriptor.charAt(i) == '(') {
            type = Type.METHOD;
        } else if (descriptor.charAt(i) == '<') {
            type = Type.GENERIC;
        } else if (descriptor.charAt(i) == 'L') {
            type = Type.MODIFIED_TYPE;
        } else {
            type = Type.BASIC;
        }
        if (type == Type.METHOD) {
            numTypesToPop += descriptor.count('(');
        }
        if (type == Type.GENERIC) {
            numTypesToPop += descriptor.count('<');
        }
        if (type == Type.MODIFIED_TYPE) {
            numTypesToPop += descriptor.count('L');
        }
        for (int j = 0; j < numTypesToPop; j++) {
            TypeReference typeExpr;
            if (descriptor.charAt(i + j) == '[') {
                typeExpr = TypeReference.find(descriptor.substring(i + j + 1));
            } else {
                typeExpr = TypeReference.find(descriptor.substring(i + j));
            }
            if (typeExpr != null) {
                if (typeExpr.getTypeTag() == TypeTag.GENERIC) {
                    numTypesToPop += typeExpr.getTypeArgumentTypes().size();
                } else if (typeExpr.getTypeTag() == TypeTag.MODIFIED) {
                    numTypesToPop += typeExpr.getModifiers().size();
                }
                typeExpr.getType().pop();
            }
        }
    }
}

public void pop(String descriptor) {
    // Step 1: Check if the descriptor is a type descriptor or a method descriptor
    if (descriptor.startsWith("(")) {
        // Step 2: If the descriptor is a method descriptor, extract the argument types
        String[] argumentTypes = getArgumentTypes(descriptor);
        // Step 3: Pop the argument types from the output frame stack
        for (String argumentType : argumentTypes) {
            pop(argumentType);
        }
    } else {
        // Step 4: Pop the type from the output frame stack
        pop(descriptor);
    }
}

private String[] getArgumentTypes(String descriptor) {
    // Step 1: Split the descriptor at the opening parenthesis
    String[] parts = descriptor.split("\\(");
    // Step 2: Return the argument types
    return parts[1].split("\\)");
}

private void pop(final String descriptor) {
    String[] tokens = descriptor.split(" ");
    int numTypes = tokens.length - 1;

    for (int i = 0; i < numTypes; i++) {
        String type = tokens[i].replaceAll("[^a-zA-Z0-9]", "");
        Object value = frame.pop();

        if (!(value instanceof type)) {
            throw new RuntimeException("Expected type " + type + " but found " + value.getClass().getName());
        }
    }
}

public void pop(final String descriptor) {
    // Check if the descriptor is a type or method descriptor
    if (!descriptor.startsWith("(")) {
        // It's a type descriptor, so we need to pop the corresponding number of abstract types
        int numAbstractTypes = getNumAbstractTypes(descriptor);
        for (int i = 0; i < numAbstractTypes; i++) {
            // Pop the abstract type
            int abstractTypeIndex = getAbstractTypeIndex(descriptor, i);
            if (abstractTypeIndex != -1) {
                AbstractType abstractType = getAbstractType(abstractTypeIndex);
                if (abstractType != null) {
                    abstractType.pop();
                } else {
                    throw new RuntimeException("Invalid abstract type");
                }
            } else {
                throw new RuntimeException("Invalid abstract type");
            }
        }
    } else {
        // It's a method descriptor, so we need to pop the arguments
        int numArguments = getNumArguments(descriptor);
        for (int i = 0; i < numArguments; i++) {
            // Pop the argument
            int argumentIndex = getArgumentIndex(descriptor, i);
            if (argumentIndex != -1) {
                Object argumentValue = getArgument(argumentIndex);
                if (argumentValue != null) {
                    // Pop the argument value
                    pop(argumentValue);
                } else {
                    throw new RuntimeException("Invalid argument");
                }
            } else {
                throw new RuntimeException("Invalid argument");
            }
        }
    }
}

private void pop(final String descriptor) {
    int numElements = getNumberOfElementsFromDescriptor(descriptor);
    for (int i = 0; i < numElements; i++) {
        if (!typeStack.isEmpty()) {
            typeStack.pop();
        } else {
            throw new PopFromEmptyStackException("Cannot pop empty type stack.");
        }
    }
}

private int getNumberOfElementsFromDescriptor(String descriptor) {
    if (descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be empty.");
    }
    int numElements = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        switch (descriptor.charAt(i)) {
            case 'L':
            case '[':
                numElements++;
                break;
            default:
                break;
        }
    }
    return numElements;
}

public void write(final byte b[], final int off, final int len) throws IOException {
    // Check for null byte array
    if (b == null) {
        throw new NullPointerException("The byte array must not be null");
    }

    // Check for invalid offset and length
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("The offset and length must be valid");
    }

    // Write the bytes to the output stream
    for (int i = off; i < off + len; i++) {
        writeByte(b[i]);
    }
}

@Override
public void write(final byte[] b, final int off, final int len) throws IOException {
    // Step 1: Check for valid input
    if (b == null) {
        throw new NullPointerException("Input byte array cannot be null");
    }
    if (off < 0 || off >= len) {
        throw new IndexOutOfBoundsException("Offset must be within the bounds of the input byte array");
    }
    if (len <= 0) {
        throw new IllegalArgumentException("Length must be greater than 0");
    }

    // Step 2: Write the bytes
    for (int i = off; i < len; i++) {
        write(b[i]);
    }
}

@Override
public void write(final byte[] b, final int off, final int len) throws IOException {
    Objects.requireNonNull(b, "Data cannot be null");
    Objects.checkIndex(off, b.length);
    Objects.checkIndex(len, b.length - off + 1);

    if (len > 0) {
        OutputStream out = getSerializedDataOutputStream();
        ByteArrayOutputStream buffer = null;
        try {
            buffer = new ByteArrayOutputStream();
            out.write(b, off, len);
            buffer.writeTo(out);
        } finally {
            if (buffer != null) {
                buffer.close();
            }
        }
    }
}

@Override
public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new IllegalArgumentException("Data must not be null");
    }
    if (off < 0 || len < 0) {
        throw new IllegalArgumentException("Offset and length must be non-negative");
    }
    if (off + len > b.length) {
        throw new IllegalArgumentException("Offset and length must be less than or equal to the length of the data");
    }
    if (len == 0) {
        return;
    }
    ensureCapacity(len);
    System.arraycopy(b, off, this.buf, this.count, len);
    this.count += len;
}

@Override
public void write(final byte[] b, final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("The data array cannot be null.");
    }
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("The start offset or length is out of bounds.");
    }
    for (int i = off; i < off + len; i++) {
        write(b[i]);
    }
}

