public void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Step 1: Validate input
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Input must not be null");
    }
    if (sourceVertex.equals(targetVertex)) {
        throw new IllegalArgumentException("Source and target vertices must be different");
    }
    if (!edges.contains(e)) {
        throw new IllegalArgumentException("Edge must be in the graph");
    }

    // Step 2: Add the edge to the index
    if (!index.containsKey(sourceVertex)) {
        index.put(sourceVertex, new HashSet<V>());
    }
    index.get(sourceVertex).add(targetVertex);

    // Step 3: Add the edge to the reverse index
    if (!reverseIndex.containsKey(targetVertex)) {
        reverseIndex.put(targetVertex, new HashSet<V>());
    }
    reverseIndex.get(targetVertex).add(sourceVertex);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    //1. check if sourceVertex and targetVertex are not null
    if (sourceVertex == null || targetVertex == null) {
        throw new IllegalArgumentException("sourceVertex and targetVertex must not be null");
    }
    //2. check if e is not null
    if (e == null) {
        throw new IllegalArgumentException("e must not be null");
    }
    //3. check if sourceVertex and targetVertex are not already in the index
    if (index.containsKey(sourceVertex) || index.containsKey(targetVertex)) {
        throw new IllegalArgumentException("sourceVertex and targetVertex must not already be in the index");
    }
    //4. add sourceVertex and targetVertex to the index
    index.put(sourceVertex, e);
    index.put(targetVertex, e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex.equals(targetVertex)) {
        // no self-loops allowed
        throw new IllegalArgumentException("Cannot add self-loop to index");
    }
    if (containsEdgeIndex(sourceVertex, targetVertex)) {
        // handle duplicate edge
        throw new IllegalArgumentException("Edge already exists in index");
    }
    // add edge to index
    vertexToEdges.put(sourceVertex, e);
    edgeToVertices.put(e, targetVertex);
}

