public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if(box.getWidth() < 2){
        throw new IllegalArgumentException("Box too small to split");
    }
    double x = box.getCenter().getX();
    Box2D box1 = new Box2D(new Point(0, 0), new Point(x, box.getHeight()));
    Box2D box2 = new Box2D(new Point(x, 0), new Point(box.getWidth(), box.getHeight()));
    return new Pair<Box2D,Box2D>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    /*
     * Step 1: Calculate the center of the box along the x axis
     * Step 2: Split the box into two parts along the center
     * Step 3: Return a pair with the two resulting boxes
     */

    // Step 1: Calculate the center of the box along the x axis
    double centerX = (box.x + box.width) / 2;

    // Step 2: Split the box into two parts along the center
    Box2D leftBox = new Box2D(box.x, box.y, centerX - box.x, box.height);
    Box2D rightBox = new Box2D(centerX, box.y, box.x + box.width - centerX, box.height);

    // Step 3: Return a pair with the two resulting boxes
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){

 # Calculate midpoint of box along x axis
 int midpoint = box.getUpperLeft().getX() + (box.getWidth() / 2);

 # Create two new boxes by dividing box along the midpoint
 Box2D box1 = new Box2D(box.getUpperLeft(), midpoint - box.getUpperLeft().getX());
 Box2D box2 = new Box2D(midpoint, box.getHeight());

 # Return the two resulting boxes
 return new Pair<Box2D,Box2D>(box1, box2);

}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box.isXAxisAligned()) {
        // If the box is already aligned along the x axis, return it as the first member of a Pair
        return new Pair<>(box, null);
    }

    // If the box is not aligned along the x axis, split it into two halves along the x axis
    Rectangle2D[] halves = box.split(new Point2D.Double(box.getCenterX(), box.getCenterY()));

    // Create a new Pair with the two resulting boxes
    return new Pair<>(new Box2D(halves[0]), new Box2D(halves[1]));
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
  // calculate the midpoint of the box along the x axis
  Point midpoint = box.getCenter().translate(-box.getWidth() / 2, 0);

  // split the box into two equal boxes
  Box2D box1 = new Box2D(box.getBottomLeft(), midpoint);
  Box2D box2 = new Box2D(midpoint, box.getTopRight());

  // return a pair of the resulting boxes
  return new Pair<>(box1, box2);
}

public void enlarge (final int size) {
if (size < 1) {
throw new IllegalArgumentException("The enlargement size must be greater than 0.");
}

// Calculate the current capacity and the required capacity.
int currentCapacity = this.getCapacity();
int requiredCapacity = this.size + size;

// If the required capacity is greater than the current capacity, resize the byte vector.
if (requiredCapacity > currentCapacity) {
int newCapacity = calculateNewCapacity(currentCapacity, requiredCapacity);
this.resize(newCapacity);
}
}

private static int calculateNewCapacity(int currentCapacity, int requiredCapacity) {
// Decide on a new capacity that is greater than or equal to the required capacity.
int newCapacity = currentCapacity < 64 ? 64 : currentCapacity + Math.max(requiredCapacity, currentCapacity / 2);
return newCapacity;
}

public void enlarge(final int size) {
    // Step 1. Check if size is valid
    if (size < 0) {
        throw new IllegalArgumentException("Enlarge method requires size >= 0");
    }

    // Step 2. Calculate the new size of the array
    int newSize = Math.abs(size) + this.size;

    // Step 3. Check if the new size is valid
    if (newSize > this.size) {
        throw new ArrayIndexOutOfBoundsException("Cannot enlarge byte vector, new size would be negative");
    }

    // Step 4. Create a new array with the new size
    byte[] newData = new byte[newSize];

    // Step 5. Copy the existing data to the new array
    System.arraycopy(this.data, 0, newData, 0, this.size);

    // Step 6. Set the data variable to the new array
    this.data = newData;
}

public void enlarge(int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be positive, was: " + size);
    }
    if (this.capacity - this.size < size) {
        int newSize = Math.max(this.capacity * 2, this.size + size);
        byte[] newData = new byte[newSize];
        System.arraycopy(this.data, 0, newData, 0, this.size);
        this.data = newData;
        this.capacity = newSize;
    }
}

private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be positive!");
    }

    // Calculate the new capacity
    int newCapacity = Math.max(size, (int) Math.ceil(this.capacity * 1.5));

    // Allocate a new array of the new capacity
    byte[] newArray = new byte[newCapacity];

    // Copy the current elements to the new array
    System.arraycopy(this.array, 0, newArray, 0, this.size);

    // Update the size and capacity fields
    this.size += size;
    this.capacity = newCapacity;

    // Replace the current array with the new one
    this.array = newArray;
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    int newCapacity = Math.max(capacity, size);
    if (newCapacity <= capacity) {
        return; // No need to enlarge
    }
    int originalCapacity = capacity;
    capacity = newCapacity;
    byte[] newData = new byte[capacity];
    System.arraycopy(data, 0, newData, 0, originalCapacity);
    data = newData;
}

