public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
	// get the first node in the buffer
	LinkedBuffer currentNode = node;
	int size = 0;

	// loop through the the buffer and write each node to the output stream
	while (currentNode != null) {
		out.write(currentNode.getData());
		size += currentNode.getSize();
		currentNode = currentNode.getNext();
	}

	// return the total size of the buffer
	return size;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int size = current.getSize();
        out.write(current.getData(), 0, size);
        totalSize += size;
        current = current.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {

    // Step 1: Serialize the contents of the LinkedBuffer into a byte array
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    DataOutputStream dos = new DataOutputStream(baos);
    int nodeCount = 0;
    while (node != null) {
        dos.write(node.getContents());
        nodeCount++;
        node = node.getNext();
    }

    // Step 2: Write the byte array to the DataOutput
    dos.writeInt(nodeCount);
    out.write(baos.toByteArray());

    // Step 3: Return the total content size of the buffer
    return baos.size();
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException{
  int contentSize = 0;
  LinkedBuffer current = node;
  while(current != null){
    contentSize += current.getContentSize();
    current = current.getNext();
  }
  out.writeInt(contentSize);
  while(node != null){
    out.write(node.getContent(), 0, node.getContentSize());
    node = node.getNext();
  }
  return contentSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {

// Step 1: Handle potential invalid inputs
if (out == null || node == null) {
throw new IllegalArgumentException("Invalid input: Output stream or linked buffer cannot be null");
}

// Step 2: Calculate the total content size of the buffer
int totalSize = 0;
while (node != null) {
totalSize += node.size();
node = node.next();
}

// Step 3: Write the buffer contents to the output stream
int written = 0;
while (node != null) {
out.write(node.getData());
written += node.size();
node = node.next();
}

// Step 4: Verify that all buffer contents were written successfully
if (written != totalSize) {
throw new IOException("Failed to write entire buffer to output stream. Written " + written + ", expected " + totalSize);
}

// Step 5: Return the total content size of the buffer
return totalSize;
}

