private void putAbstractTypes(final int start, final int end) {
    // Handle invalid inputs
    if (start < 0 || end < 0 || start > end || end > currentFrame.getSize()) {
        throw new IllegalArgumentException("Invalid start or end index");
    }

    // Write the types in the current frame to the stack map table entries
    for (int i = start; i < end; i++) {
        Object type = currentFrame.get(i);
        if (type instanceof String) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.STRING, (String) type));
        } else if (type instanceof Integer) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.INTEGER, (Integer) type));
        } else if (type instanceof Float) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.FLOAT, (Float) type));
        } else if (type instanceof Double) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.DOUBLE, (Double) type));
        } else if (type instanceof Long) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.LONG, (Long) type));
        } else if (type instanceof Boolean) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.BOOLEAN, (Boolean) type));
        } else if (type instanceof Byte) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.BYTE, (Byte) type));
        } else if (type instanceof Short) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.SHORT, (Short) type));
        } else if (type instanceof Char) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.CHAR, (Char) type));
        } else if (type instanceof Array) {
            stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntryType.ARRAY, (Array) type));
        } else {
            throw new IllegalArgumentException("Invalid type");
        }
    }
}

