      System.arraycopy(buffer, 0, temp, 0, buffer.length);
      in.read(temp, buffer.length, len);
      buffer = temp;
    }
  }
}

@Override public void write(final byte[] b) throws IOException {
    if (b == null) {
        throw new NullPointerException("Buffer is null");
    }

    int len = b.length;
    int offset = 0;
    int count = 0;

    while (len > 0) {
        count = write(b, offset, Math.min(len, (int) Math.min(len, Integer.MAX_VALUE)));
        offset += count;
        len -= count;
    }
}

