public String toJson(JSONWriter.Feature... features) {
    // Step 1: Validate input parameters
    if (features == null || features.length == 0) {
        throw new IllegalArgumentException("No features specified for serialization");
    }
    for (JSONWriter.Feature feature : features) {
        if (feature == null) {
            throw new IllegalArgumentException("Null feature found in the list of serialization features");
        }
    }

    // Step 2: Create a new JSON string builder
    StringBuilder json = new StringBuilder("{");

    // Step 3: Iterate over the features and serialize each one
    for (int i = 0; i < features.length; i++) {
        JSONWriter.Feature feature = features[i];
        json.append("\"").append(feature.getName()).append("\":");
        json.append(feature.getValue().toString());
        if (i < features.length - 1) {
            json.append(",");
        }
    }

    // Step 4: Close the JSON object and return the resulting string
    json.append("}");
    return json.toString();
}

