@Override protected Character convertToType(final Class<?> type,final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (value instanceof java.lang.Character) {
        return (Character) value;
    }
    if (value instanceof java.lang.String) {
        String strValue = (String) value;
        if (strValue.length() == 1) {
            return strValue.charAt(0);
        }
    } else if (value instanceof java.lang.Boolean) {
        Boolean boolValue = (Boolean) value;
        if (boolValue) {
            return Character.TRUE;
        }
    } else if (value instanceof java.lang.Number) {
        Number numValue = (Number) value;
        if (numValue.doubleValue() == Math.floor(numValue.doubleValue())) {
            return (char) numValue.intValue();
        }
    }
    throw new Exception("The value '" + value + "' is not convertible to type Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    Object convertedValue = null;
    if (value != null) {
        if (type == Character.class) {
            if (value instanceof Character) {
                convertedValue = value;
            } else if (value instanceof String) {
                String stringValue = (String) value;
                if (stringValue.length() == 1) {
                    convertedValue = stringValue.charAt(0);
                } else {
                    throw new Exception("Cannot convert string of length > 1 to Character");
                }
            } else {
                throw new Exception("Cannot convert " + value.getClass().getName() + " to Character");
            }
        } else {
            throw new Exception("Unsupported conversion from " + value.getClass().getName() + " to " + type.getName());
        }
    }
    return convertedValue;
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
if (type == null) {
throw new IllegalArgumentException("Type to convert to must not be null");
}
if (value == null) {
throw new IllegalArgumentException("Value to convert must not be null");
}
if (type.isAssignableFrom(value.getClass())) {
return value;
}
if (type.isPrimitive()) {
return convertToPrimitiveType(type, value);
}
if (type.isAssignableFrom(String.class)) {
return value.toString();
}
throw new RuntimeException("Could not convert value of type " + value.getClass().getName() + " to type " + type.getName());
}

private Object convertToPrimitiveType(Class<?> type, Object value) {
if (type == boolean.class) {
return Boolean.parseBoolean(value.toString());
} else if (type == byte.class) {
return Byte.parseByte(value.toString());
} else if (type == short.class) {
return Short.parseShort(value.toString());
} else if (type == int.class) {
return Integer.parseInt(value.toString());
} else if (type == long.class) {
return Long.parseLong(value.toString());
} else if (type == float.class) {
return Float.parseFloat(value.toString());
} else if (type == double.class) {
return Double.parseDouble(value.toString());
} else if (type == char.class) {
return value.toString().charAt(0);
} else {
throw new RuntimeException("Could not convert value of type " + value.getClass().getName() + " to primitive type " + type.getName());
}
}

