public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 2) {
    return 2;
  }

  int capacity = (int) (desiredCapacity / 1.1 + 1);

  while (!isPrime(capacity)) {
    capacity++;
  }

  return capacity;
}

private static boolean isPrime(int num) {
  if (num < 2) {
    return false;
  }

  for (int i = 2; i <= Math.sqrt(num); i++) {
    if (num % i == 0) {
      return false;
    }
  }

  return true;
}

public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 2) {
    return 2;
  }
  // Find the next prime number greater than or equal to the desired capacity
  int prime = 2;
  while (prime < desiredCapacity) {
    if (isPrime(prime)) {
      break;
    }
    prime++;
  }
  // If the prime number is too far away from the desired capacity, return the next prime number
  if (prime - desiredCapacity > 0.11 * desiredCapacity && desiredCapacity >= 1000) {
    return prime + 1;
  }
  return prime;
}

private static boolean isPrime(int n) {
  if (n <= 1) {
    return false;
  }
  for (int i = 2; i <= Math.sqrt(n); i++) {
    if (n % i == 0) {
      return false;
    }
  }
  return true;
}

