public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    String result = str;
    Pattern pattern = Pattern.compile("\\\\.");
    Matcher matcher = pattern.matcher(str);
    while (matcher.find()) {
        String escapeSequence = matcher.group();
        switch (escapeSequence) {
            case "\\b":
                result = result.replace(escapeSequence, "\b");
                break;
            case "\\t":
                result = result.replace(escapeSequence, "\t");
                break;
            case "\\n":
                result = result.replace(escapeSequence, "\n");
                break;
            case "\\f":
                result = result.replace(escapeSequence, "\f");
                break;
            case "\\r":
                result = result.replace(escapeSequence, "\r");
                break;
            default:
                throw new Exception("Invalid escape sequence: " + escapeSequence);
        }
    }
    return result;
}

