        # If the value is a list, convert it to a JSON array
        if isinstance(value, list):
            value = [convert_property(item) for item in value]

        # If the value is a dict, convert it to a JSON object
        if isinstance(value, dict):
            value = {key: convert_property(item) for item in value.items()}

        # Add the key and value to the source data
        source_data[key] = value

    return source_data

def convert_property(property):
    if not property:
        return None

    # Prepare the property for JSON conversion
    property = property.strip().replace("\"", "'")

    # If the property is a string, convert it to a JSON string
    if isinstance(property, str):
        return property

    # If the property is a list or dict, convert it to a JSON array or object
    if isinstance(property, (list, dict)):
        return convert_property(property)

    # If the property is anything else, return it as-is
    return property

private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    if (properties == null || properties.isEmpty()) {
        throw new IllegalArgumentException("Properties list is empty or null");
    }

    JsonObject sourceData = new JsonObject();
    for (KeyStringValuePair property : properties) {
        Object value = property.getValue();
        if (value instanceof String) {
            sourceData.addProperty(property.getKey(), (String) value);
        } else if (value instanceof Integer) {
            sourceData.addProperty(property.getKey(), (Integer) value);
        } else if (value instanceof Double) {
            sourceData.addProperty(property.getKey(), (Double) value);
        } else if (value instanceof JsonObject) {
            sourceData.add(property.getKey(), (JsonObject) value);
        } else {
            throw new IllegalArgumentException("Unsupported value type for property " + property.getKey());
        }
    }
    return sourceData;
}

