private int removeUnusedNodes(Node node) {
    int numRemoved = 0;
    if (node == null) {
        return numRemoved;
    }
    if (node.isInactive()) {
        numRemoved++;
        node.getParent().setChild(node.getPosition(), null);
    } else {
        numRemoved += removeUnusedNodes(node.getLeft());
        numRemoved += removeUnusedNodes(node.getRight());
    }
    return numRemoved;
}

