    if (c < '0' || (c > '9' && c < 'A') || c > 'F') {
        throw new IllegalArgumentException("Invalid hexadecimal character: " + c);
    }
    // Convert the character to uppercase
    char upperCaseC = Character.toUpperCase(c);
    // Subtract the ASCII value of '0' to get the corresponding digit
    int digit = upperCaseC - '0';
    // If the character is a letter, subtract the ASCII value of 'A' to get the corresponding letter
    if (digit > 9) {
        digit -= 'A' - '0';
    }
    return (char) digit;
}

