    /* Step 1: Check if the character is in the range [0-9a-fA-F] */
    if (!(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F')) {
        return Character.MAX_VALUE;
    }

    /* Step 2: Convert the character to a hexadecimal value */
    int hexValue = Integer.parseInt(String.valueOf(c), 16);

    /* Step 3: Return the hexadecimal value as a character */
    return (char) hexValue;
}

