private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    // Initialize a circulator to the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Iterate through the outer face nodes
    while (!circ.isAt(stop)) {
        // If the current node satisfies the predicate, return a circulator to it
        if (predicate.test(circ.getNode())) {
            return circ;
        }

        // Move to the next node in the outer face
        circ.moveRight(dir);
    }

    // If we reached the stop node without finding a satisfying node, return a circulator to the stop node
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {

/**
 * Starts at the given node and traverses the boundary of the component in the given direction. If a node that satisfies
 * the given predicate is found, a circulator to that node is returned. Otherwise, a circulator to the stop node is returned.
 */

// check if the start node satisfies the predicate
if (predicate.test(start)) {
return new OuterFaceCirculator(start, dir);
}

// traverse the boundary of the component in the given direction
Node current = start;
while (current != stop) {
current = current.getNext(dir);

// check if the current node satisfies the predicate
if (predicate.test(current)) {
return new OuterFaceCirculator(current, dir);
}
}

// if no node satisfying the predicate was found, return a circulator to the stop node
return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    if (predicate.test(start)) {
        return circulator;
    }
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Step 1: Traverse the outer face of the component in the given direction
    //         until the stop node is reached or the predicate is satisfied.
    //         Keep track of the node on the boundary that satisfies the predicate.
    Node boundaryNode = null;
    Node currentNode = start;
    while (currentNode != stop && boundaryNode == null) {
        if (predicate.test(currentNode)) {
            boundaryNode = currentNode;
        }
        currentNode = currentNode.getNextAtDistance(dir);
    }

    // Step 2: If a boundary node satisfying the predicate was found, return a circulator to it.
    //         Otherwise, return a circulator to the stop node.
    if (boundaryNode != null) {
        return new OuterFaceCirculator(boundaryNode, dir);
    } else {
        return new OuterFaceCirculator(stop, dir);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node current = circulator.getCurrent();
    while (!current.equals(stop)) {
        if (predicate.test(current)) {
            return circulator;
        }
        circulator.moveToNext();
        current = circulator.getCurrent();
    }
    return circulator;
}

