private String unescapeId(String input){
    // Step 1: Initialize variables
    // Declare a new String to store the unescaped output
    String unescapedOutput = "";
    // Iterate through each character in the input string
    for (int i = 0; i < input.length(); i++) {
        // Get the current character
        char currentChar = input.charAt(i);
        // Check if the current character is an escape character
        if (currentChar == '\\') {
            // If the current character is an escape character, check the next character
            char nextChar = input.charAt(i + 1);
            // Escape the next character if necessary
            if (nextChar == '\"') {
                unescapedOutput += "\"";
                i++;
            } else if (nextChar == '\\') {
                unescapedOutput += "\\";
                i++;
            } else {
                throw new IllegalArgumentException("Invalid escape character: " + currentChar);
            }
        } else {
            // If the current character is not an escape character, add it to the output string as is
            unescapedOutput += currentChar;
        }
    }
    return unescapedOutput;
}

