public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
  // STEP 1: Check for null or empty input
  if (bucketsByLabel == null || bucketsByLabel.isEmpty() || labels == null || labels.isEmpty()) {
    throw new IllegalArgumentException("Invalid input: bucketsByLabel or labels is null or empty");
  }

  // STEP 2: Check if minLabel is valid
  if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
    throw new IllegalArgumentException("Invalid minimum value of non-empty bucket: " + minLabel);
  }

  // STEP 3: Create a temporary bucket to hold vertices with minLabel
  Set<Integer> tempBucket = new HashSet<>();

  // STEP 4: Iterate over the buckets and move all vertices with minLabel to the temporary bucket
  for (int i = 0; i < bucketsByLabel.size(); i++) {
    if (i == minLabel) {
      tempBucket.addAll(bucketsByLabel.get(i));
      bucketsByLabel.get(i).clear();
    }
  }

  // STEP 5: Update the labels of the vertices in the temporary bucket
  for (int vertex : tempBucket) {
    labels.set(vertex, 0);
  }

  // STEP 6: Clear the bucket with minLabel
  bucketsByLabel.get(minLabel).clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Iterate over the bucket with the minimum label and move its vertices to the bucket with label 0
    Set<Integer> bucketWithMinLabel = bucketsByLabel.get(minLabel);
    for (Integer vertex : bucketWithMinLabel) {
        labels.set(vertex, 0);
        bucketsByLabel.get(0).add(vertex);
    }
    // Clear the bucket with the minimum label
    bucketWithMinLabel.clear();
}

