public static int countOccurrencesOf(String str, String sub) {
  // Check if either str or sub are null, return 0 if so
  if (str == null || sub == null) {
    return 0;
  }

  // Initialize a counter for the number of occurrences
  int count = 0;

  // Loop through each character in str
  for (int i = 0; i < str.length(); i++) {
    // Check if the current character is the first character of sub
    if (str.charAt(i) == sub.charAt(0)) {
      // Check if the rest of the string matches sub
      if (str.substring(i).startsWith(sub)) {
        // Increment the counter
        count++;
      }
    }
  }

  // Return the number of occurrences
  return count;
}

