public Class<?> findClass(String className) throws ClassNotFoundException {

  Class<?> clazz = null;

  // Check if the class name is not null
  if (className != null) {
    // Try to load the class using the class loader
    try {
      clazz = Class.forName(className);
    } catch (ClassNotFoundException e) {
      // If the class is not found, throw an exception
      throw new ClassNotFoundException("Class not found: " + className, e);
    }
  } else {
    // If the class name is null, throw an exception
    throw new IllegalArgumentException("Class name cannot be null");
  }

  return clazz;
}

