public boolean isTemplateVariablePresent(String name){
    if(name == null){
        return false;
    }
    name = name.trim();
    if(!name.contains("{{") && !name.contains("}}"){
        return false;
    }
    //check for matching brackets
    int openBracketCount = 0;
    for(char c : name.toCharArray()){
        if(c == '{{'){
            openBracketCount++;
        }else if(c == '}}'){
            openBracketCount--;
        }
        if(openBracketCount < 0){
            break;
        }
    }
    return openBracketCount == 0;
}

public void putAllWriteable(BeanMap map) {
  try {
    // Check if the input BeanMap is null
    if (map == null) {
      throw new IllegalArgumentException("The input BeanMap cannot be null.");
    }

    // Iterate through the input BeanMap's properties
    for (Map.Entry<String, Object> property : map.entrySet()) {
      // Check if the current property is read-only
      if (!property.getValue().getAccessor().isWriteAllowed()) {
        continue;
      }

      // Put the property into this BeanMap
      put(property.getKey(), property.getValue());
    }
  } catch (IllegalArgumentException | UnsupportedOperationException e) {
    throw new RuntimeException("Unexpected exception occurred while putting writeable properties.", e);
  }
}

public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("Map must not be null");
    }
    for (Object key : map.keySet()) {
        if (map.isWritable(key)) {
            this.put(key, map.get(key));
        }
    }
}

public void putAllWriteable(BeanMap map) {
