public static Meteor lookup(HttpServletRequest r) {
    // Retrieve the request URI and query string
    String requestUrl = r.getRequestURL().toString();
    String queryString = r.getQueryString();

    // Parse the query string to extract the keyword parameter
    Map<String, String> params = parseQueryString(queryString);
    String keyword = params.get("keyword");

    // Retrieve the meteor instance from the cache
    return Meteor.getInstance(keyword);
}

private static Map<String, String> parseQueryString(String queryString) {
    if (queryString == null || queryString.isEmpty()) {
        return Collections.emptyMap();
    }

    String[] parts = queryString.split("&");
    Map<String, String> params = new HashMap<>();

    for (String part : parts) {
        String[] keyValue = part.split("=");
        if (keyValue.length == 2) {
            params.put(keyValue[0], keyValue[1]);
        }
    }

    return params;
}

public static Meteor lookup(HttpServletRequest r) {
    if (r == null) {
        return null;
    }

    String path = r.getRequestURI();
    Matcher matcher = METEOR_PATTERN.matcher(path);

    try {
        if (matcher.find()) {
            String name = matcher.group(1);
            return METEOR_SERVICE.getMeteorByName(name);
        }
    } catch (NumberFormatException e) {
        LOGGER.warning("Invalid meteor name in request: " + path);
        return null;
    }

    return null;
}

