private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    // Initialize an empty list to store the global separator list
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E e : graph.edges()) {
        // Compute the minimal separators of edge e in its neighborhood
        List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparators = computeMinimalSeparators(e);

        // Add the minimal separators to the global separator list
        globalSeparatorList.addAll(minimalSeparators);
    }

    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeMinimalSeparators(E e){
    // Initialize an empty list to store the minimal separators
    List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparators = new ArrayList<>();

    // Get the neighborhood of edge e
    List<E> neighborhood = getEdgeNeighborhood(e);

    // Iterate over all edges in the neighborhood
    for (E e2 : neighborhood) {
        // Check if edge e2 is a minimal separator of edge e
        if (isMinimalSeparator(e, e2)) {
            // Add edge e2 and its edge with the minimum cardinality to the list of minimal separators
            minimalSeparators.add(new Pair<>(List.of(e2, e2.otherThan(e)), e));
        }
    }

    return minimalSeparators;
}

private List<E> getEdgeNeighborhood(E e){
    // Get the two vertices incident to edge e
    V v1 = e.getFirstVertex();
    V v2 = e.getSecondVertex();

    // Initialize an empty list to store the neighborhood
    List<E> neighborhood = new ArrayList<>();

    // Iterate over all edges incident to vertex v1
    for (E e2 : v1.edges()) {
        // Check if edge e2 is in the neighborhood of edge e
        if (e2 != e && e2.otherThan(e).contains(v2)) {
            // Add edge e2 to the neighborhood
            neighborhood.add(e2);
        }
    }

    // Iterate over all edges incident to vertex v2
    for (E e2 : v2.edges()) {
        // Check if edge e2 is in the neighborhood of edge e
        if (e2 != e && e2.otherThan(e).contains(v1)) {
            // Add edge e2 to the neighborhood
            neighborhood.add(e2);
        }
    }

    return neighborhood;
}

private boolean isMinimalSeparator(E e, E e2){
    // Compute the neighborhood of edge e2
    List<E> neighborhood = getEdgeNeighborhood(e2);

    // Check if edge e is a separator of edge e2 in its neighborhood
    if (!neighborhood.contains(e)) {
        return false;
    }

    // Check if edge e is a minimal separator of edge e2
    for (E e3 : neighborhood) {
        if (e3 != e && e3.otherThan(e2).size() < e.otherThan(e2).size()) {
            return false;
        }
    }

    return true;
}

public static List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> separators = new ArrayList<>();

    graph.vertexSet().forEach(v -> {
        List<E> edges = graph.edgesOf(v);
        for (E edge : edges) {
            List<Pair<Integer, Integer>> separator = new ArrayList<>();
            separator.add(new Pair<>(v.id(), edge.getSource().id()));
            separator.add(new Pair<>(v.id(), edge.getTarget().id()));

            separators.add(new Pair<>(separator, edge));
        }
    });

    return separators;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edgeSet()) {
        List<Pair<Integer, Integer>> edgeSeparator = computeSeparator(graph, e);
        globalSeparatorList.add(new Pair<>(edgeSeparator, e));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer,Integer>> localSeparators = computeLocalSeparators(edge);
        globalSeparatorList.add(Pair.<List<Pair<Integer,Integer>>,E>of(localSeparators, edge));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer,Integer>> localSeparatorList = computeLocalSeparatorList(edge);
        Pair<List<Pair<Integer,Integer>>,E> separatorPair = new Pair<>(localSeparatorList, edge);
        globalSeparatorList.add(separatorPair);
    }
    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeLocalSeparatorList(E edge) {
    List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();
    for (int i = 0; i < vertical.size(); i++) {
        for (int j = i + 1; j < vertical.size(); j++) {
            int weight = weight(edge, i, j);
            if (weight > 0) {
                localSeparatorList.add(new Pair<>(i, j));
            }
        }
    }
    return localSeparatorList;
}

private int weight(E edge, int i, int j) {
    int weight = 0;
    for (int k = 0; k < vertical.size(); k++) {
        if (k != i && k != j && weight(edge, k, i) > 0 && weight(edge, k, j) > 0) {
            weight++;
        }
    }
    return weight;
}

