public static void selectRow(int row,JTable table,JScrollPane pane){
    if (table == null) {
        throw new IllegalArgumentException("Table must not be null");
    }
    if (pane == null) {
        throw new IllegalArgumentException("Pane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index");
    }
    table.setRowSelectionInterval(row, row);
    pane.getViewport().setViewPosition(new Point(0, row * table.getRowHeight()));
    table.repaint();
    try {
        Thread.sleep(100);
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Step 1: Check if the table and scroll pane are not null
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and scroll pane cannot be null");
    }

    // Step 2: Check if the specified row is valid
    if (row < 0 || row >= table.getRowCount()) {
        throw new IndexOutOfBoundsException("Row index out of bounds");
    }

    // Step 3: Select the row in the table
    table.setRowSelectionInterval(row, row);

    // Step 4: Scroll the scroll pane to the newly selected row
    pane.scrollRectToVisible(table.getCellRect(row, 0, false));

    // Step 5: Repaint the table to show the newly selected row
    table.repaint();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
  // Check if the row is valid
  if (row < 0 || row >= table.getRowCount()) {
    throw new IllegalArgumentException("Invalid row: " + row);
  }

  // Scroll the scroll pane to the specified row
  int rowY = table.getRowHeight() * row;
  pane.getVerticalScrollBar().setValue(rowY);

  // Select the row
  table.changeSelection(row, 0, false, true);

  // Repaint the table to update the selection
  table.repaint();

  // Wait for the repaint to complete
  try {
    Thread.sleep(50);
  } catch (InterruptedException e) {
    e.printStackTrace();
  }
}

