public ByteVector putInt(final int intValue) {
    // Step 1: Check if the byte vector has enough capacity to store the int value
    if (this.writerIndex + 4 > this.storage.length) {
        // If the current buffer is not large enough, create a new buffer with double the capacity
        byte[] newStorage = new byte[this.storage.length * 2];
        // Copy the contents of the current buffer to the new buffer
        System.arraycopy(this.storage, 0, newStorage, 0, this.writerIndex);
        this.storage = newStorage;
    }

    // Step 2: Put the int value into the byte vector
    for (int i = 0; i < 4; i++) {
        this.storage[this.writerIndex + i] = (byte) (intValue >>> (8 * i));
    }

    // Step 3: Increment the writer index
    this.writerIndex += 4;

    return this;
}

public ByteVector putInt(final int intValue) {
    // Resize the byte vector if necessary
    if (intValue > 0 && intValue > this.length) {
        resize(intValue);
    }

    // Convert the int value into a sequence of bytes
    byte[] bytes = intToBytes(intValue);

    // Put the bytes into the byte vector
    for (byte b : bytes) {
        this.put(b);
    }

    return this;
}

public ByteVector putInt(final int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("intValue must be non-negative");
    }
    int size = intValue.bitLength();
    if (size > 32) {
        throw new IllegalArgumentException("intValue exceeds the maximum size of 32 bits");
    }
    int paddingSize = 32 - size;
    byte[] bytes = new byte[4];
    for (int i = 0; i < 4; i++) {
        bytes[i] = (byte) ((intValue >>> (24 - i * 8)) & 0xFF);
    }
    return new ByteVector(bytes, 0, size + paddingSize);
}

private ByteVector putInt(final int intValue) {
    // Step 1: Check if the given value is within the range of an int.
    if (intValue < Integer.MIN_VALUE || intValue > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("The given value is outside the range of an int.");
    }

    // Step 2: Extend the capacity of the byte vector if necessary.
    if (intValue > capacity()) {
        ensureCapacity(intValue);
    }

    // Step 3: Add the int value to the byte vector.
    putInt0(intValue);

    // Step 4: Return the modified byte vector.
    return this;
}

