public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Step 1: Handle null input
    if (typeVariable == null) {
        return Unknown.class;
    }

    // Step 2: Resolve the bound of the type variable
    Type type = typeVariable.getBounds()[0];
    if (type instanceof Class) {
        return type;
    } else if (type instanceof TypeVariable) {
        return type;
    } else {
        return Unknown.class;
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Step 1: Check if the type variable is null
    if (typeVariable == null) {
        throw new IllegalArgumentException("Type variable cannot be null");
    }

    // Step 2: Check if the type variable has a bound
    Type bound = typeVariable.getBounds()[0];
    if (bound == null) {
        return Unknown.class;
    }

    // Step 3: Resolve the bound
    if (bound instanceof Class) {
        return bound;
    } else if (bound instanceof TypeVariable) {
        return resolveBound((TypeVariable<?>) bound);
    } else {
        throw new UnsupportedOperationException("Unknown bound type: " + bound.getClass().getName());
    }
}

