    Optional<Type> bound = Arrays.stream(typeVariable.getBounds()).findFirst();
    return bound.orElse(Unknown.class);
 }

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return false;
    }
    // Check if the graph is complete
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex != otherVertex) {
                if (!graph.containsEdge(vertex, otherVertex)) {
                    return false;
                }
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Edge case: no vertices or only one vertex
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }

    // Check if all vertices are connected
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // check if the subgraph induced by the given vertices is complete, i.e. a clique
    boolean isClique = true;
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (!graph.containsEdge(vertex, otherVertex)) {
                isClique = false;
                break;
            }
        }
    }
    return isClique;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("graph and vertices cannot be null");
    }

    if (vertices.size() <= 1) {
        return true;
    }

    Set<V> adjacentVertices = new HashSet<>();
    for (V vertex : vertices) {
        adjacentVertices.addAll(graph.getAdjacentVertices(vertex));
    }

    return adjacentVertices.size() == vertices.size() && adjacentVertices.containsAll(vertices);
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
	// Check if the vertices induce a complete subgraph
	if (vertices.size() < 2) {
		// If there are fewer than 2 vertices, return False
		return false;
	}

	// Get the maximum degree of the subgraph
	int maxDegree = 0;
	for (V vertex : vertices) {
		int degree = graph.degreeOf(vertex);
		if (degree > maxDegree) {
			maxDegree = degree;
		}
	}

	// Check if the max degree is equal to the number of vertices
	if (maxDegree == vertices.size()) {
		// If the max degree is equal to the number of vertices, return True
		return true;
	} else {
		// If the max degree is not equal to the number of vertices, return False
		return false;
	}
}

private List<Integer> computeLowerBounds(List<K> keys) {

    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        List<Integer> bounds = new ArrayList<>();
        for (K otherKey : keys) {
            if (key.equals(otherKey)) {
                continue;
            }
            bounds.add(Math.min(key.hashCode(), otherKey.hashCode()));
        }
        lowerBounds.add(Collections.min(bounds));
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // Sort the list of keys in descending order
    Collections.sort(keys, Collections.reverseOrder());

    // Initialize the lower bound for each key to the maximum value possible
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        lowerBounds.add(Integer.MAX_VALUE);
    }

    // Iterate over the sorted list of keys and update the lower bound for each key
    for (int i = 0; i < keys.size(); i++) {
        int currentLowerBound = lowerBounds.get(i);
        for (int j = i + 1; j < keys.size(); j++) {
            if (keys.get(j) <= currentLowerBound) {
                currentLowerBound = keys.get(j);
                break;
            }
        }
        lowerBounds.set(i, currentLowerBound);
    }

    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize a list to store the lower bounds for each key
    List<Integer> lowerBounds = new ArrayList<Integer>();

    // Loop through each key in the input list
    for (K key : keys) {
        // Initialize the lower bound for the current key
        int lowerBound = Integer.MAX_VALUE;

        // Loop through each sublist in the input list
        for (List<K> sublist : keys) {
            // Check if the current sublist contains the current key
            if (sublist.contains(key)) {
                // Update the lower bound for the current key
                lowerBound = Math.min(lowerBound, sublist.size());
            }
        }

        // Add the lower bound for the current key to the output list
        lowerBounds.add(lowerBound);
    }

    return lowerBounds;
}

