    }

    List<AbstractType> abstractTypes = new ArrayList<>();
    String[] typeParameters = descriptor.split("\\(");
    for(int i = 0; i < typeParameters.length; i++){
        String typeParameter = typeParameters[i];
        if(!typeParameter.isEmpty()){
            AbstractType abstractType = AbstractType.getType(typeParameter);
            if(abstractType != null){
