private void pop(final String descriptor) {
    // Step 1: Determine the number of abstract types to pop
    int numAbstractTypes = getNumAbstractTypes(descriptor);

    // Step 2: Pop the abstract types from the output frame stack
    for (int i = 0; i < numAbstractTypes; i++) {
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor) {
    // Step 1: Parse the type descriptor to determine the number of types to pop.
    int numTypesToPop = getNumTypesToPop(descriptor);

    // Step 2: Pop the appropriate number of types from the output frame stack.
    for (int i = 0; i < numTypesToPop; i++) {
        popType();
    }
}

private int getNumTypesToPop(String descriptor) {
    // Step 1: Split the descriptor into tokens.
    String[] tokens = descriptor.split(" ");

    // Step 2: Count the number of types in the descriptor.
    int numTypes = 0;
    for (String token : tokens) {
        if (isType(token)) {
            numTypes++;
        }
    }

    return numTypes;
}

private boolean isType(String token) {
    // Step 1: Check if the token is a primitive type.
    if (token.equals("Z") || token.equals("B") || token.equals("C") || token.equals("S") || token.equals("I") ||
            token.equals("J") || token.equals("F") || token.equals("D") || token.equals("V")) {
        return true;
    }

    // Step 2: Check if the token is an array type.
    if (token.startsWith("[") && token.endsWith(")")) {
        return true;
    }

    // Step 3: Check if the token is a class type.
    if (token.startsWith("L") && token.endsWith(";")) {
        return true;
    }

    return false;
}

private void popType() {
    // Step 1: Check if the output frame stack is empty.
    if (outputFrameStack.isEmpty()) {
        throw new RuntimeException("Cannot pop type from empty output frame stack.");
    }

    // Step 2: Pop the top type from the output frame stack.
    outputFrameStack.pop();
}

private void pop(final String descriptor) {
    try {
        int numTypesToPop = descriptor.split("\\(\\)").length - 1;
        for (int i = 0; i < numTypesToPop; i++) {
            popType();
        }
    } catch (EmptyStackException e) {
        // TODO: Handle exception
    }
}

