public static boolean equals(Point2D p1,Point2D p2){
    // compare x and y coordinates of the two points
    if (Math.abs(p1.getX() - p2.getX()) > 1e-9 || Math.abs(p1.getY() - p2.getY()) > 1e-9) {
        return false;
    }
    return true;
}

public static boolean equals(Point2D p1, Point2D p2) {
    // Check if the points are the same object
    if (p1 == p2) {
        return true;
    }

    // Check if the points are null
    if (p1 == null || p2 == null) {
        return false;
    }

    // Check if the x and y coordinates are within the given tolerance
    if (Math.abs(p1.getX() - p2.getX()) <= 1e-9 && Math.abs(p1.getY() - p2.getY()) <= 1e-9) {
        return true;
    }

    return false;
}

public static boolean equals(Point2D p1, Point2D p2) {
    double tolerance = 1e-9;
    double dx = Math.abs(p1.x - p2.x);
    double dy = Math.abs(p1.y - p2.y);
    return (dx <= tolerance && dy <= tolerance);
}

