public static String applyRelativePath(String path, String relativePath) {
    // Validate input
    if (path == null || relativePath == null) {
        throw new NullPointerException("Input path or relative path cannot be null");
    }
    if (!path.trim().isEmpty() && !relativePath.trim().isEmpty()) {
        throw new IllegalArgumentException("Input path or relative path cannot be empty");
    }
    if (!path.contains("/")) {
        throw new IllegalArgumentException("Input path must contain at least one '/' separator");
    }

    // Handle relative paths starting with "/"
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Handle relative paths containing "../"
    while (relativePath.contains("../")) {
        int index = relativePath.indexOf("../");
        String dir = path.substring(0, path.lastIndexOf("/", index));
        relativePath = relativePath.substring(index + 3);
        path = dir + relativePath;
    }

    return path;
}

public static String applyRelativePath(String path, String relativePath) {
  // check if the path is empty or null
  if (path == null || path.isEmpty()) {
    throw new IllegalArgumentException("Path cannot be empty or null");
  }

  // check if the relative path is empty or null
  if (relativePath == null || relativePath.isEmpty()) {
    throw new IllegalArgumentException("Relative path cannot be empty or null");
  }

  // check if the path starts with a "/"
  if (!path.startsWith("/")) {
    throw new IllegalArgumentException("Path must start with a '/'");
  }

  // check if the relative path starts with a "/"
  if (!relativePath.startsWith("/")) {
    throw new IllegalArgumentException("Relative path must start with a '/'");
  }

  // strip any leading or trailing "/" from the path and relative path
  path = path.strip().stripLeading(path.charAt(0));
  relativePath = relativePath.strip().stripLeading(path.charAt(0));

  // split the path and relative path into arrays
  String[] pathParts = path.split("/");
  String[] relativePathParts = relativePath.split("/");

  // apply the relative path to the path
  for (String part : relativePathParts) {
    if (part.equals("..")) {
      if (pathParts.length > 0) {
        pathParts = pathParts.dropRight(1);
      } else {
        throw new IllegalArgumentException("Relative path is invalid");
      }
    } else if (part.equals(".")) {
      // do nothing
    } else {
      pathParts.add(part);
    }
  }

  // join the path parts into a single string
  path = pathParts.join("/");

  return path;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be empty");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be empty");
    }
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");
    for (int i = 0; i < relativePathParts.length; i++) {
        if (relativePathParts[i].equals("..")) {
            if (pathParts.length == 0) {
                throw new IllegalArgumentException("Path cannot be empty");
            }
            pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
        } else if (!relativePathParts[i].equals(".")) {
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = relativePathParts[i];
        }
    }
    return String.join("/", pathParts);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }
    if (!path.endsWith("/")) {
        path += "/";
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }
    return path + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
  // Check if the relative path is valid
  if (relativePath == null || relativePath.isEmpty()) {
    return path;
  }

  // Split the relative path into its components
  String[] components = relativePath.split("/");

  // Check if the relative path is absolute
  if (components[0].equals("")) {
    return components[components.length - 1];
  }

  // Split the path into its components
  String[] pathComponents = path.split("/");

  // Iterate over the relative path components and apply them to the path
  for (int i = 0; i < components.length; i++) {
    String component = components[i];
    if (component.equals("..")) {
      // Go up one directory
      pathComponents = pathComponents.substring(0, pathComponents.length - 1);
    } else if (component.equals(".")) {
      // Stay in the same directory
      // Do nothing
    } else {
      // Go down into a subdirectory
      pathComponents.push(component);
    }
  }

  // Join the path components back together and return the resulting path
  return pathComponents.join("/");
}

