public Edge edgeToNext() {
    if (currentNode == null || nextNode == null) {
        throw new IllegalStateException("Both currentNode and nextNode must be non-null");
    }

    if (currentNode.isVirtual()) {
        if (nextNode.isVirtual()) {
            // Both nodes are virtual, so we need to find the real counterparts
            currentNode = currentNode.getRealCounterpart();
            nextNode = nextNode.getRealCounterpart();
        } else {
            // Only currentNode is virtual, so we need to find its real counterpart
            currentNode = currentNode.getRealCounterpart();
        }
    } else if (nextNode.isVirtual()) {
        // Only nextNode is virtual, so we need to find its real counterpart
        nextNode = nextNode.getRealCounterpart();
    }

    // Now we have the real counterparts of both nodes, so we can create the edge
    return new Edge(currentNode, nextNode);
}

