private String buildContentRange(int start, int end, int total) {
    // Validate input
    if (start < 0 || end < 0 || total < 0) {
        throw new IllegalArgumentException("Invalid input: Start and end index must be non-negative, and total must be greater than or equal to 0");
    }
    // Build the 'Content-Range' value
    return String.format("items %d-%d/%d", start, end, total);
}

private String buildContentRange(){
    // 1. initialize variables
    String contentRange = "";
    int start = getStart();
    int end = getEnd();
    int total = getTotal();

    // 2. generate contentRange value
    contentRange = "bytes " + start + "-" + end + "/" + total;

    // 3. return contentRange
    return contentRange;
}

public String buildContentRange() {
    // Initialize the variable to hold the Content-Range value
    String contentRange = null;

    // Check if the Content-Range is not null and is a valid range
    if (contentRange != null && contentRange.contains("bytes")) {
        // Extract the range values from the Content-Range string
        String[] rangeValues = contentRange.split("bytes=");
        int start = 0;
        int end = 0;
        try {
            start = Integer.parseInt(rangeValues[0]);
            end = Integer.parseInt(rangeValues[1]);
        } catch (NumberFormatException e) {
            // Handle the exception and return null
            return null;
        }

        // Build the Content-Range value using the extracted range values
        contentRange = "bytes " + start + "-" + end + "/*";
    }

    return contentRange;
}

private String buildContentRange() {
    // Retrieve the 'Range' header value from the request
    String range = getRequest().getHeader("Range");

    // Parse the 'Range' header value to extract the start and end offsets
    int startOffset = Integer.parseInt(range.substring(0, range.indexOf("-")));
    int endOffset = Integer.parseInt(range.substring(range.indexOf("-") + 1));

    // Calculate the length of the content range
    int contentLength = endOffset - startOffset + 1;

    // Build the 'Content-Range' header value
    String contentRange = "bytes " + startOffset + "-" + endOffset + "/" + contentLength;

    return contentRange;
}

private String buildContentRange(int start, int end, int total) throws IllegalArgumentException {

  if (start < 0 || end < 0 || total < 0) {
    throw new IllegalArgumentException("Start, end, and total parameters must be non-negative.");
  }

  if (start > end) {
    throw new IllegalArgumentException("Start parameter must be less than or equal to the end parameter.");
  }

  return " bytes " + start + "-" + end + "/" + total;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Step 1: Check if file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new FileNotFoundException("File does not exist or is not readable: " + file.getAbsolutePath());
    }
    // Step 2: Check if time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be null or empty");
    }
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.getStartTime() > timeRange.getEndTime()) {
            throw new IllegalArgumentException("Invalid time range: start time cannot be after end time");
        }
    }
    // Step 3: Read the file and parse the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Check if the line is a thread snapshot
            if (line.startsWith("THREAD SNAPSHOT")) {
                // Parse the line and create a ThreadSnapshot object
                String[] parts = line.split("\\t");
                if (parts.length < 4) {
                    throw new IOException("Invalid thread snapshot format: " + line);
                }
                ThreadSnapshot snapshot = new ThreadSnapshot(parts[1], parts[2], parts[3], parts[4]);
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (snapshot.getTimeStamp() >= timeRange.getStartTime() && snapshot.getTimeStamp() <= timeRange.getEndTime()) {
                        threadSnapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error parsing thread snapshot file", e);
    }
    // Return the list of thread snapshots
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

// Step 1: Read file contents
String fileContents = new String(Files.readAllBytes(file.toPath()));

// Step 2: Extract thread snapshots from file contents
List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
Pattern threadSnapshotPattern = Pattern.compile("^\s*-+\s*Snapshot\s*-\s*(\d+)\s*\( (\w+) \s*\)");
Matcher threadSnapshotMatcher = threadSnapshotPattern.matcher(fileContents);
while (threadSnapshotMatcher.find()) {
String snapshotId = threadSnapshotMatcher.group(1);
String snapshotSource = threadSnapshotMatcher.group(2);

// Step 3: Extract stack trace from thread snapshot
Pattern stackTracePattern = Pattern.compile("^(\s*)Stack:\s*(.*)$", Pattern.MULTILINE);
Matcher stackTraceMatcher = stackTracePattern.matcher(fileContents);
if (stackTraceMatcher.find()) {
String stackTrace = stackTraceMatcher.group(2);

// Step 4: Extract thread information from stack trace
Map<String, String> threadInfo = new LinkedHashMap<>();
Pattern threadInfoPattern = Pattern.compile("^(\w+)\(([\w.$]+)\)");
Matcher threadInfoMatcher = threadInfoPattern.matcher(stackTrace);
while (threadInfoMatcher.find()) {
String threadName = threadInfoMatcher.group(1);
String threadId = threadInfoMatcher.group(2);
threadInfo.put(threadName, threadId);
}

// Step 5: Filter thread snapshots based on time range
boolean isSnapshotInRange = false;
for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
if (timeRange.contains(Long.parseLong(snapshotId))) {
isSnapshotInRange = true;
break;
}
}

// Step 6: Add thread snapshot to list
if (isSnapshotInRange) {
ThreadSnapshot snapshot = new ThreadSnapshot(snapshotId, snapshotSource, threadInfo);
threadSnapshots.add(snapshot);
}
}
}

return threadSnapshots;
}

public ThreadSnapshot(String id, String source, Map<String, String> threadInfo) {
this.id = id;
this.source = source;
this.frames = new ArrayList<>();

for (Map.Entry<String, String> entry : threadInfo.entrySet()) {
String key = entry.getKey();
String value = entry.getValue();
frames.add(String.format("%s: %s", key, value));
}
}

public String getId() {
return id;
}

public String getSource() {
return source;
}

public List<String> getFrames() {
return frames;
}

public ProfileAnalyzeTimeRange(long start, long end) {
this.start = start;
this.end = end;
}

public boolean contains(long time) {
return time >= start && time <= end;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a file");
    }

    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("timeRanges must not be null or empty");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Read the file line by line
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = reader.readLine();
        while (line != null) {
            // Parse the line as a thread snapshot
            ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
            if (threadSnapshot != null) {
                // Check if the snapshot falls within one of the time ranges
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange.contains(threadSnapshot.getTimestampMillis())) {
                        threadSnapshots.add(threadSnapshot);
                        break;
                    }
                }
            }
            line = reader.readLine();
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) 
  throws IOException {
  List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

  BufferedReader bufferedReader = new BufferedReader(new FileReader(file));
  String line;
  while ((line = bufferedReader.readLine()) != null) {
    ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromLine(line);
    if (threadSnapshot != null) {
      if (isInTimeRange(threadSnapshot, timeRanges)) {
        threadSnapshots.add(threadSnapshot);
      }
    }
  }
  return threadSnapshots;
}

private static boolean isInTimeRange(ThreadSnapshot threadSnapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
  for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
    if (threadSnapshot.getTimestamp() >= timeRange.getStart() && threadSnapshot.getTimestamp() <= timeRange.getEnd()) {
      return true;
    }
  }
  return false;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: file or timeRanges is null or empty");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
            if (threadSnapshot == null) {
                continue;
            }

            boolean inTimeRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (threadSnapshot.getTimestamp() >= timeRange.getStartTime() && threadSnapshot.getTimestamp() <= timeRange.getEndTime()) {
                    inTimeRange = true;
                    break;
                }
            }

            if (inTimeRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    return threadSnapshots;
}
